    <p style="margin:0 0 6px 0;color:#fca5a5;font-weight:bold;">🚧 Safety Notes (Classroom and Fieldwork)</p>
    <div>
    <ul style="margin:6px 0;padding-left:22px;">
    <li>When examining folded rocks in road cuttings, keep well away from traffic and loose rock.</li>
    </ul>
