    <div style="background:#3e2723;padding:20px;border-radius:12px;border:1px solid #64b5f6;margin-bottom:20px;">
    <h3 style="color:#e3f2fd;margin-top:0;">🧠 Lesson Summary</h3>
    <p>Vulcanicity is the movement of magma and gases into the crust or onto the surface. Magma rises through lines of weakness. Intrusive vulcanicity forms batholiths, dykes, sills, laccoliths, lopoliths and phacoliths as magma cools underground, producing large-crystal rocks such as granite. These features provide building stone, minerals, waterfalls and scenery when exposed.</p>
    <h4 style="color:#e3f2fd;margin:16px 0 6px 0;">🗒️ Revision notes</h4>
    <ul style="margin:6px 0;padding-left:22px;">
    <li>Vulcanicity.</li>
    <li>Magma vs lava.</li>
    <li>Intrusive features.</li>
    <li>Significance.</li>
    </ul>
    </div>
